-- ETAPA 21: PPE catalog, stock and worker history. Quantities move only through the transactional delivery function.
create table public.ppe_catalog (id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete restrict,code text not null check(code ~ '^[A-Z0-9][A-Z0-9_-]{1,80}$'),name text not null check(btrim(name)<>''),description text,category text not null check(btrim(category)<>''),useful_life_days integer check(useful_life_days is null or useful_life_days>0),status text not null default 'active' check(status in ('draft','active','archived')),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,code));
create table public.ppe_catalog_hazards (ppe_catalog_id uuid not null references public.ppe_catalog(id) on delete cascade,hazard_id uuid not null references public.hazard_catalog(id) on delete restrict,created_at timestamptz not null default now(),primary key(ppe_catalog_id,hazard_id));
create table public.ppe_catalog_controls (ppe_catalog_id uuid not null references public.ppe_catalog(id) on delete cascade,risk_control_id uuid not null references public.risk_controls(id) on delete restrict,organization_id uuid not null references public.organizations(id) on delete restrict,created_at timestamptz not null default now(),primary key(ppe_catalog_id,risk_control_id));
create table public.ppe_inventory (id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete restrict,site_id uuid references public.sites(id) on delete restrict,ppe_catalog_id uuid not null references public.ppe_catalog(id) on delete restrict,size_label text not null default '' check(char_length(size_label)<=40),quantity_on_hand integer not null default 0 check(quantity_on_hand>=0),reorder_point integer check(reorder_point is null or reorder_point>=0),updated_at timestamptz not null default now(),unique nulls not distinct(organization_id,site_id,ppe_catalog_id,size_label));
create table public.ppe_assignments (id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete restrict,organization_member_id uuid not null references public.organization_members(id) on delete restrict,site_id uuid references public.sites(id) on delete restrict,ppe_catalog_id uuid not null references public.ppe_catalog(id) on delete restrict,size_label text not null default '' check(char_length(size_label)<=40),status text not null default 'active' check(status in ('active','returned','retired')),assigned_at timestamptz not null default now(),expected_replacement_at date,created_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now());
create table public.ppe_deliveries (id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete restrict,ppe_assignment_id uuid not null references public.ppe_assignments(id) on delete restrict,inventory_id uuid not null references public.ppe_inventory(id) on delete restrict,quantity integer not null check(quantity>0),delivered_at timestamptz not null default now(),accepted_at timestamptz,accepted_by uuid references auth.users(id) on delete set null,evidence_document_version_id uuid references public.document_versions(id) on delete restrict,created_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now());
create table public.ppe_inspections (id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete restrict,ppe_assignment_id uuid not null references public.ppe_assignments(id) on delete restrict,status text not null check(status in ('suitable','needs_replacement','failed')),notes text,inspected_at timestamptz not null default now(),inspected_by uuid references auth.users(id) on delete set null,evidence_document_version_id uuid references public.document_versions(id) on delete restrict,created_at timestamptz not null default now());
create table public.ppe_retirements (id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete restrict,ppe_assignment_id uuid not null references public.ppe_assignments(id) on delete restrict,reason text not null check(btrim(reason)<>''),retired_at timestamptz not null default now(),evidence_document_version_id uuid references public.document_versions(id) on delete restrict,retired_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now(),unique(ppe_assignment_id));
create index ppe_inventory_org_site_idx on public.ppe_inventory(organization_id,site_id,ppe_catalog_id); create index ppe_assignments_member_idx on public.ppe_assignments(organization_id,organization_member_id,status); create index ppe_deliveries_assignment_idx on public.ppe_deliveries(ppe_assignment_id); create index ppe_inspections_assignment_idx on public.ppe_inspections(ppe_assignment_id,inspected_at desc); create index ppe_retirements_assignment_idx on public.ppe_retirements(ppe_assignment_id);
insert into public.permissions(code,module,action,description) values ('ppe.read','ppe','read','Consultar inventario e historial de EPP.'),('ppe.manage','ppe','manage','Gestionar catálogo, inventario y asignaciones de EPP.'),('ppe.validate','ppe','validate','Registrar entregas, aceptación, inspección y baja de EPP.') on conflict(code) do nothing;
insert into public.role_permissions(role_id,permission_id) select r.id,p.id from public.roles r join public.permissions p on p.code in ('ppe.read','ppe.manage','ppe.validate') where r.code='organization_admin' and r.organization_id is null on conflict do nothing;
create or replace function private.validate_ppe_tenant_links() returns trigger language plpgsql security definer set search_path='' as $$ begin
 if tg_table_name='ppe_catalog_controls' and (not exists(select 1 from public.ppe_catalog where id=new.ppe_catalog_id and organization_id=new.organization_id) or not exists(select 1 from public.risk_controls where id=new.risk_control_id and organization_id=new.organization_id)) then raise exception 'ppe control link belongs to another organization' using errcode='23514'; end if;
 if tg_table_name='ppe_inventory' and (new.site_id is not null and not exists(select 1 from public.sites where id=new.site_id and organization_id=new.organization_id) or not exists(select 1 from public.ppe_catalog where id=new.ppe_catalog_id and organization_id=new.organization_id)) then raise exception 'ppe inventory link belongs to another organization' using errcode='23514'; end if;
 if tg_table_name='ppe_assignments' and (not exists(select 1 from public.organization_members where id=new.organization_member_id and organization_id=new.organization_id and status='active') or not exists(select 1 from public.ppe_catalog where id=new.ppe_catalog_id and organization_id=new.organization_id) or (new.site_id is not null and not exists(select 1 from public.sites where id=new.site_id and organization_id=new.organization_id))) then raise exception 'ppe assignment belongs to another organization' using errcode='23514'; end if;
 if tg_table_name in ('ppe_deliveries','ppe_inspections','ppe_retirements') and not exists(select 1 from public.ppe_assignments where id=new.ppe_assignment_id and organization_id=new.organization_id) then raise exception 'ppe event belongs to another organization' using errcode='23514'; end if;
 if tg_table_name='ppe_deliveries' and not exists(select 1 from public.ppe_inventory where id=new.inventory_id and organization_id=new.organization_id) then raise exception 'ppe inventory belongs to another organization' using errcode='23514'; end if;
 if tg_table_name in ('ppe_deliveries','ppe_inspections','ppe_retirements') and new.evidence_document_version_id is not null and not exists(select 1 from public.document_versions where id=new.evidence_document_version_id and organization_id=new.organization_id) then raise exception 'ppe evidence belongs to another organization' using errcode='23514'; end if; return new; end; $$;
create or replace function private.deliver_ppe(p_assignment_id uuid,p_inventory_id uuid,p_quantity integer,p_evidence_document_version_id uuid default null) returns uuid language plpgsql security definer set search_path='' as $$ declare a public.ppe_assignments%rowtype;i public.ppe_inventory%rowtype;d uuid; begin select * into a from public.ppe_assignments where id=p_assignment_id for update; select * into i from public.ppe_inventory where id=p_inventory_id for update; if not found or a.organization_id<>i.organization_id or p_quantity<=0 or i.quantity_on_hand<p_quantity then raise exception 'invalid PPE delivery or insufficient stock' using errcode='23514'; end if; if not private.has_permission(a.organization_id,'ppe.validate') then raise exception 'insufficient PPE permission' using errcode='42501'; end if; update public.ppe_inventory set quantity_on_hand=quantity_on_hand-p_quantity where id=i.id; insert into public.ppe_deliveries(organization_id,ppe_assignment_id,inventory_id,quantity,evidence_document_version_id,created_by) values(a.organization_id,a.id,i.id,p_quantity,p_evidence_document_version_id,(select auth.uid())) returning id into d; return d; end; $$;
revoke all on function private.validate_ppe_tenant_links(),private.deliver_ppe(uuid,uuid,integer,uuid) from public,anon,authenticated,service_role; grant execute on function private.deliver_ppe(uuid,uuid,integer,uuid) to authenticated;
alter table public.ppe_catalog enable row level security; alter table public.ppe_catalog_hazards enable row level security; alter table public.ppe_catalog_controls enable row level security; alter table public.ppe_inventory enable row level security; alter table public.ppe_assignments enable row level security; alter table public.ppe_deliveries enable row level security; alter table public.ppe_inspections enable row level security; alter table public.ppe_retirements enable row level security;
grant select,insert,update on public.ppe_catalog,public.ppe_catalog_hazards,public.ppe_catalog_controls,public.ppe_inventory,public.ppe_assignments to authenticated; grant select,insert on public.ppe_deliveries,public.ppe_inspections,public.ppe_retirements to authenticated;
create policy ppe_catalog_read on public.ppe_catalog for select to authenticated using((select private.has_permission(organization_id,'ppe.read'))); create policy ppe_catalog_write on public.ppe_catalog for all to authenticated using((select private.has_permission(organization_id,'ppe.manage'))) with check((select private.has_permission(organization_id,'ppe.manage')));
create policy ppe_inventory_read on public.ppe_inventory for select to authenticated using((select private.has_permission(organization_id,'ppe.read'))); create policy ppe_inventory_write on public.ppe_inventory for all to authenticated using((select private.has_permission(organization_id,'ppe.manage'))) with check((select private.has_permission(organization_id,'ppe.manage')));
create policy ppe_assignments_read on public.ppe_assignments for select to authenticated using((select private.has_permission(organization_id,'ppe.read'))); create policy ppe_assignments_write on public.ppe_assignments for all to authenticated using((select private.has_permission(organization_id,'ppe.manage'))) with check((select private.has_permission(organization_id,'ppe.manage')));
create policy ppe_events_read on public.ppe_deliveries for select to authenticated using((select private.has_permission(organization_id,'ppe.read'))); create policy ppe_deliveries_insert on public.ppe_deliveries for insert to authenticated with check((select private.has_permission(organization_id,'ppe.validate')));
create policy ppe_inspections_read on public.ppe_inspections for select to authenticated using((select private.has_permission(organization_id,'ppe.read'))); create policy ppe_inspections_insert on public.ppe_inspections for insert to authenticated with check((select private.has_permission(organization_id,'ppe.validate')));
create policy ppe_retirements_read on public.ppe_retirements for select to authenticated using((select private.has_permission(organization_id,'ppe.read'))); create policy ppe_retirements_insert on public.ppe_retirements for insert to authenticated with check((select private.has_permission(organization_id,'ppe.validate')));
create policy ppe_catalog_hazards_read on public.ppe_catalog_hazards for select to authenticated using((select exists(select 1 from public.ppe_catalog c where c.id=ppe_catalog_id and private.has_permission(c.organization_id,'ppe.read')))); create policy ppe_catalog_hazards_write on public.ppe_catalog_hazards for all to authenticated using((select exists(select 1 from public.ppe_catalog c where c.id=ppe_catalog_id and private.has_permission(c.organization_id,'ppe.manage')))) with check((select exists(select 1 from public.ppe_catalog c where c.id=ppe_catalog_id and private.has_permission(c.organization_id,'ppe.manage'))));
create policy ppe_catalog_controls_read on public.ppe_catalog_controls for select to authenticated using((select private.has_permission(organization_id,'ppe.read'))); create policy ppe_catalog_controls_write on public.ppe_catalog_controls for all to authenticated using((select private.has_permission(organization_id,'ppe.manage'))) with check((select private.has_permission(organization_id,'ppe.manage')));
create trigger ppe_inventory_links before insert or update on public.ppe_inventory for each row execute function private.validate_ppe_tenant_links(); create trigger ppe_assignments_links before insert or update on public.ppe_assignments for each row execute function private.validate_ppe_tenant_links(); create trigger ppe_deliveries_links before insert on public.ppe_deliveries for each row execute function private.validate_ppe_tenant_links(); create trigger ppe_inspections_links before insert on public.ppe_inspections for each row execute function private.validate_ppe_tenant_links(); create trigger ppe_retirements_links before insert on public.ppe_retirements for each row execute function private.validate_ppe_tenant_links(); create trigger ppe_catalog_controls_links before insert or update on public.ppe_catalog_controls for each row execute function private.validate_ppe_tenant_links();
create trigger ppe_catalog_audit after insert or update on public.ppe_catalog for each row execute function private.capture_core_audit(); create trigger ppe_inventory_audit after insert or update on public.ppe_inventory for each row execute function private.capture_core_audit(); create trigger ppe_assignments_audit after insert or update on public.ppe_assignments for each row execute function private.capture_core_audit(); create trigger ppe_deliveries_audit after insert on public.ppe_deliveries for each row execute function private.capture_core_audit(); create trigger ppe_inspections_audit after insert on public.ppe_inspections for each row execute function private.capture_core_audit(); create trigger ppe_retirements_audit after insert on public.ppe_retirements for each row execute function private.capture_core_audit();
notify pgrst,'reload schema';
